(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["hr"] = {"ui":{"skip":"Preskoči na sadržaj","back":"← Natrag na AI-gile","lang.button":"Jezik: {name}","lang.dialog":"Odaberi jezik","lang.search":"Traži jezike","lang.none":"Nijedan jezik ne odgovara","lang.notYet":"{name} još nije preveden","theme.aria":"Promijeni temu: svijetla, tamna ili crna","theme.toLight":"Prebaci na svijetlu temu","theme.toDark":"Prebaci na tamnu temu","theme.toBlack":"Prebaci na crnu temu (prava crna, ugodna za OLED ekrane)","words.underline":"Podcrtaj ove riječi na stranici","words.underlineHelp":"Prijeđi mišem preko riječi s točkastom crtom ili je dodirni da vidiš što znači.","words.col.todo":"Kartice odabrane za sada: tim sljedeće kreće s njima.","words.col.doing":"Neki AI trenutačno radi na ovoj kartici.","words.col.review":"Jedan je AI završio posao; drugi ga provjerava prije nego stigne do tebe.","words.col.verify":"Čeka se tebe: isprobaj i reci radi li.","words.col.team":"Tvoje bilješke ili odgovori, koji čekaju da ih tim preuzme.","words.col.done":"Gotovo i prihvaćeno.","index.title":"AI-gile: tvoj AI razvojni tim, na jednoj ploči","index.description":"AI-gile je kanban ploča za AI timove koji programiraju. Rade dok ti spavaš; tebi ostaje jedna kratka hrpa stvari koje trebaš odlučiti, testirati i prihvatiti.","hero.logoAlt":"Ikona AI-gile ploče","hero.h1.html":"Tvoj AI razvojni tim, na jednoj&nbsp;ploči.","hero.alpha":"🐣 Zatvorena pre-alfa","hero.alphaTitle":"Rano je i nedovršeno: hvala što isprobavaš!","hero.lede":"Grade dok ti spavaš. Budiš se uz jednu kratku hrpu: nekoliko pitanja, nekoliko stvari za testiranje, jedan ili dva ljubičasta dijamanta. Klikneš, prihvatiš, vratiš se kavi.","dl.windows":"Windows aplikacija","dl.browser":"Pokreni u pregledniku","dl.messenger":"📱 Messenger za tvoj mobitel","dl.soon":"Uskoro","dl.notify":"🔔 Javi mi kad se otvori","dl.notifySmall":"Alfa ili beta","hero.secondary":"Agile, ali timu ne treba stand-up kava. (Stand-up ipak održavaju.)","pitch.h2":"AI-gile u onoliko riječi koliko želiš","pitch.lede":"Odaberi duljinu, od jedne riječi do 144. Svaka duljina ima svoj opis, napisan baš za tu veličinu. Povuci klizač ili koristi strelice.","pitch.rangeLabel":"Duljina u riječima","pitch.dice":"🎲 druga verzija","pitch.words.one":"{n} riječ","pitch.words.other":"{n} riječi","pitch.letters.one":"{n} slovo","pitch.letters.other":"{n} slova","pitch.chars.one":"{n} znak","pitch.chars.other":"{n} znakova","count.line.html.one":"{n} kartica na ploči upravo sada","count.line.html.other":"{n} kartica na ploči upravo sada","people.humans.html.one":"👥 {n} čovjek","people.humans.html.other":"👥 {n} ljudi","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agenata","people.working.html.one":"⚡ {n} radi upravo sada","people.working.html.other":"⚡ {n} radi upravo sada","pre.title":"AI-gile: ovdje se nešto gradi","pre.description":"Ovdje se nešto gradi. Ploča na kojoj AI timovi grade ono što tražiš i usput te uče. Zasad zatvorena pre-alfa s prijateljima.","pre.h1":"Ovdje se nešto gradi. 🤫","pre.line":"Ploča na kojoj AI timovi grade ono što tražiš i usput te uče. Zasad zatvorena pre-alfa s prijateljima.","pre.btn":"🔔 Javi mi kad se otvori","pre.peek":"Iza stakla: prava ploča, uživo. Svaka kartica je obojena traka.","pre.peekFake":"Iza stakla: ovako izgleda ploča u radu.","pre.night":"🌙 Noćni čuvar je zadužen · 😴 čovjek odmara","features.aria":"Što radi","f.pile.h":"Jedna hrpa za tebe","f.pile.html":"<b>Za tebe</b> sadrži sve što čeka tebe, kroz sve projekte: pitanja, stvari za testiranje, zadatke koje može obaviti samo čovjek. Tvoj red kaže što je sljedeće i koliko traje.","f.sleep.h":"Timovi koji rade dok ti spavaš","f.sleep.p":"Svaki projekt ima lead i tim AI agenata. Komentiraj karticu i tim se budi, odradi posao i vrati je s koracima koje može pratiti i umoran čovjek.","f.tester.h":"AI tester provjerava prvi","f.tester.p":"Prije nego išta stigne do tebe, tester prati korake u kopiji aplikacije i pokazuje što je vidio, sa snimkom zaslona. Prelistaj one koje su prošle i prihvati jednim klikom.","f.proof.h":"Dokazi, ne obećanja","f.proof.p":"Svaka primopredaja pokazuje što se promijenilo: datoteke, diff, snimke zaslona. Ne moraš otvarati svaku aplikaciju da vidiš je li gotovo.","f.chat.h":"Razgovaraj sa svojim leadovima","f.chat.p":"Traka u stilu Discorda: jedna ikona po projektu, ljubičasti dijamanti za ono što treba tebe. Pošalji leadu ideju; pretvorit će je u kartice i plan, s gumbom ✅ Go.","f.tidy.h":"Sam se uredi","f.tidy.p":"Povezane kartice stapaju se u jednu, zbrkani naslovi se ispravljaju, a provjera tokena drži kod vitkim. Manje stvari između kojih se prebacuješ, manje razmišljanja.","f.private.h":"Tvoje, na tvom računalu","f.private.li1":"Ploča radi na tvom računalu i odgovara samo tebi.","f.private.li2":"Privatne poruke među ljudima šifrirane su od kraja do kraja.","f.private.li3":"Bez računa, bez tragača, bez kolačića.","f.lang.h":"Na tvom jeziku","f.lang.p":"Više od 120 jezika, od nizozemskog, velškog i japanskog do gusarskog, Yode i klingonskog, s brzim povratkom na engleski za stručne pojmove.","f.service.h":"Od ideje do pravog servisa","f.service.p":"Napravio si nešto s AI-jem što ljudi sada koriste? Označi to kao servis i ploča ti pomaže da ga dobro vodiš: provjere dostupnosti, javna statusna stranica, incidenti s pisanom analizom, promjene kojima treba Go, sigurnosne kopije provjerene svaki dan. Pomoć te uči svaki korak usput.","msgr.h2":"AI-gile Messenger: tvoj tim u džepu","msgr.p1":"Razgovaraj sa svojim AI timom bez otvaranja ploče. Dopisuj se s leadovima svojih projekata i s prijateljima, pogledaj korake testiranja kartice i odgovori na njih, sve s mobitela.","msgr.p2":"Za uparivanje skeniraj QR kod na svojoj ploči. Prvi put? Prijateljski demo razgovor provest će te kroz sve.","msgr.when":"Prvo Android, zatim web verzija za mobitele i iPhone.","msgr.who":"Lead tvog projekta","msgr.b1":"Popravak tamnog načina je spreman. Želiš korake za testiranje?","msgr.b2":"Da, molim!","msgr.b3":"1. Otvori Postavke. 2. Odaberi Tamna. Izgleda li dobro?","tl.aria":"Vremenska crta od prvog razgovora do plana","tl.h2":"Od prvog razgovora do onoga što slijedi","tl.lede":"Pravi datumi i vremena, u tvojoj vremenskoj zoni. Nakon današnjeg dana to je plan, bez obećanih datuma.","tl.today":"Danas","tl.planned":"planirano","tl.doing":"u tijeku","tl.cards.one":"{n} kartica","tl.cards.other":"{n} kartica","join.h2":"Pridruži se","join.lede":"AI-gile gradi jedan bradati čudak s AuDHD-om i nekoliko bitaka s psihičkim zdravljem te velik broj strpljivih agenata. Zasad je privatan, u zatvorenoj alfi s prijateljima. Želiš li probati kad se otvori?","join.btn":"Prijavi interes","join.small":"Javit ćemo ti se e-poštom, ništa više","footer.tag":"AI-gile. Bez tragača, bez kolačića, bez stand-up kave.","footer.licence":"Poslovna licenca","footer.status":"Status","footer.privacy":"Što čuvamo","footer.thanks":"Pozive omogućuje ChilledChat","form.sending":"Šaljem…","form.failed":"Nije uspjelo: pokušaj ponovno kasnije.","form.offline":"Nije moguće doći do AI-gilea: pokušaj ponovno kasnije.","form.keep":"Ovo koristimo samo da ti odgovorimo, a zatim brišemo. Bez tragača, bez kolačića.","form.keepLink":"Što čuvamo","interest.title":"AI-gile: javi mi kad se alfa otvori","interest.description":"Ostavi e-adresu da saznaš kad se otvori zatvorena alfa ili beta AI-gilea.","interest.h1":"🔔 Javi mi kad se otvori","interest.lede":"AI-gile je u zatvorenoj pre-alfi. Ostavi e-adresu i javit ćemo se jednom, kad bude mjesta za tebe.","interest.email":"Tvoja e-adresa","interest.which":"Koje testiranje?","interest.alpha":"Zatvorena alfa: rano, grubo, puno promjena","interest.beta":"Beta: stabilnija, kasnije","interest.both":"Svejedno, što prije dođe","interest.submit":"Stavi me na popis","interest.thanks":"Hvala! Na popisu si.","licence.title":"AI-gile: poslovna licenca","licence.description":"Koristiš AI-gile u poslu? Zatraži besplatnu poslovnu licencu.","licence.h1":"📜 Poslovna licenca","licence.lede":"Koristiš AI-gile na poslu? Reci nam tko si i čime se baviš. Ako donosi nešto dobro, licenca je besplatna.","licence.company":"Tvrtka","licence.website":"Web-stranica","licence.what":"Čime se baviš","licence.how":"Kako to pomaže svijetu","licence.email":"E-adresa","licence.submit":"Prijavi se","licence.thanks":"Hvala! Odgovorit ćemo e-poštom.","status.title":"Status AI-gilea","status.h1":"Status AI-gilea","status.quiet":"Sve je mirno","status.intro":"Radi li AI-gile upravo sada? Ova stranica svakih 5 minuta provjerava web-stranicu, dijeljenje ploča, pozive i preuzimanje.","status.up":"Radi (odgovor stigao za {ms} ms)","status.slow":"Bez odgovora na zadnju provjeru, pokušavam ponovno","status.down":"Ne radi: bez odgovora na zadnje dvije provjere","status.svc.web":"Web-stranica","status.svc.web.offers":"Ova stranica: što je AI-gile i obrazac za prijavu interesa","status.svc.boards":"Dijeljenje ploča","status.svc.boards.offers":"Javne ploče, poruke među prijateljima i pozivnice","status.svc.calls":"Pozivi","status.svc.calls.offers":"Glas, video i dijeljenje zaslona u AI-gileu","status.svc.download":"Preuzimanje","status.svc.download.offers":"Instalacijski program za Windows i poveznice pozivnica","status.checking":"Provjeravam…","status.offline":"Trenutno nije moguće doći do statusne usluge (pokušavam ponovno)","status.updated":"ažurirano {ago}","status.justNow":"upravo sada","status.min":"prije {n} min","status.hours":"prije {n} h","status.days":"prije {n} d","privacy.title":"AI-gile: što čuvamo","privacy.h1":"Što čuvamo","privacy.lede":"Ukratko: samo ono što nam pošalješ, i to ne dugo.","privacy.only":"Samo ono što nam pošalješ: ono što upišeš u obrazac, poput tvoje e-adrese. Ništa drugo o tebi.","privacy.sealed":"Zapečaćeno je tako da ga naš poslužitelj ne može pročitati: u tvom pregledniku prije nego što krene (u starijem pregledniku, čim stigne). Otvoriti ga može samo naša vlastita ploča.","privacy.server":"Briše se s poslužitelja čim stigne na našu ploču. Sve što je ondje i nakon 30 dana svejedno se briše.","privacy.board":"Na našoj ploči čuvamo ga samo dok ti ne odgovorimo, a onda ga brišemo i ondje.","privacy.none":"Bez tragača, bez kolačića, bez analitike.","privacy.local":"Tvoj jezik i izbor svijetle ili tamne teme ostaju u tvom pregledniku. Nikad nam se ne šalju.","privacy.ask":"Želiš da nestane prije? Odgovori na našu poruku e-pošte i javi nam.","live.h2":"Gledajte kako se gradi, uživo","live.caption":"Svaka kartica je skrivena: vidite oblik posla, a ne riječi.","live.watching.one":"uživo: {n} gleda","live.watching.other":"uživo: {n} gleda","live.last.now":"Zadnja kartica premještena upravo sada","live.last.min.one":"Zadnja kartica premještena prije {n} min","live.last.min.other":"Zadnja kartica premještena prije {n} min","live.last.hour.one":"Zadnja kartica premještena prije {n} sat","live.last.hour.other":"Zadnja kartica premještena prije {n} sati","live.last.day.one":"Zadnja kartica premještena prije {n} dan","live.last.day.other":"Zadnja kartica premještena prije {n} dana","live.offline":"Ploča uživo malo odmara. Svratite uskoro.","live.cols":"Backlog|Na redu|U tijeku|Tim provjerava|Za tvoje testiranje|Za tim|Gotovo","pitch.words.few":"{n} riječi","pitch.letters.few":"{n} slova","pitch.chars.few":"{n} znaka","count.line.html.few":"{n} kartice na ploči upravo sada","tl.cards.few":"{n} kartice"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Delegirano."]},{"n":2,"texts":["Kanban robota.","Agenti, posloženi.","Ideje, izgrađene."]},{"n":3,"texts":["Kanban za robote.","Ideje postaju značajke.","Besplatni agentski kanban."]},{"n":5,"texts":["Kanban ploča koju vode agenti.","Ti pišeš kartice. Agenti grade.","Besplatno, lokalno, testirano, pomalo ludo."]},{"n":8,"texts":["Besplatna kanban ploča na kojoj rade AI agenti.","Napiši ideju. Agenti je grade. Ti prihvaćaš.","Agile za jednog čovjeka i mnogo strpljivih robota."]},{"n":13,"texts":["Kanban ploča na tvom računalu, a kartice preuzimaju AI agenti i rade ih.","Napiši ideju. Tim agenata je izgradi. Tester je provjeri prije tebe.","Besplatno, bez računa, bez tragača: ploča, nekoliko robota i ti kao šef."]},{"n":21,"texts":["AI-gile je kanban ploča za rad s AI agentima koji programiraju. Oni preuzimaju kartice; ti ih testiraš i prihvaćaš.","Svaki projekt dobiva lead i tim AI agenata. Komentiraj bilo koju karticu i tim odmah kreće raditi.","Besplatna osobna ploča zadataka koja radi na tvom računalu. Radnici su roboti. Onaj koji kaže da si ti."]},{"n":34,"texts":["Ideje stavljaš na ploču. Tim AI agenata pretvara ih u značajke koje rade, testira ih i vraća ti ih s koracima za isprobavanje. Ništa ne vrijedi kao gotovo dok ti to ne kažeš.","AI-gile je domaća kanban ploča koju je Rich izgradio uz mnogo pomoći agenata kojima sada upravlja. Besplatna je, radi na tvom računalu i dijeli se s prijateljima, ne prodaje se.","Zamisli običnu kanban ploču sa stupcima od Backloga do Gotovo, samo što kartice preuzimaju AI agenti. Javljaju napredak, pitaju kad zapnu i uvijek čekaju tvoj palac gore."]},{"n":55,"texts":["AI-gile je kanban ploča na kojoj je tim sastavljen od AI agenata. Svaki projekt ima lead koji planira posao i pomoćnike koji ga grade. Kad je značajka gotova, AI tester je isproba i snimi zaslon, a zatim stiže na tvoju hrpu. Prihvati je ili komentiraj pa je prerade.","Počelo je kao jedan način da jedna osoba prati mnogo AI programerskih sesija odjednom, a preraslo je u pravu ploču. Radi na tvom računalu, ne traži račun i nema tragača. Besplatna je za prijatelje i svakoga tko je znatiželjan. Također je nedovršena, pa očekuj grube rubove i poneko iznenađenje.","Evo poštene verzije, bez uljepšavanja. I dalje ti moraš imati ideje i provjeravati rezultate. AI-gile radi sve između: drži kartice u redu, budi pravog agenta kad komentiraš, pokazuje točno što se promijenilo, tko je to napravio i sve to drži na jednoj kratkoj hrpi za tebe."]},{"n":89,"texts":["AI-gile je besplatna kanban ploča koju pokrećeš na vlastitom računalu. Umjesto ljudi, svaki projekt ima tim AI agenata: lead koji tvoje ideje pretvara u kartice i plan te pomoćnike koji preuzimaju kartice po prioritetu. Kad je nešto izgrađeno, AI tester prati korake testiranja i pokazuje ti što je vidio. Zatim sve čeka na jednoj hrpi nazvanoj Za tebe. Prihvatiš to ili komentiraš pa tim pokuša ponovno. Ništa ne stiže u Gotovo bez tebe.","Nekoliko stvari koje možda ne očekuješ. Noćni čuvar dopunjuje stupac Na redu dok ti spavaš, birajući kartice kojima ne treba tvoj odgovor. Brojač tokena pokazuje koliko su agenti potrošili danas i ovaj tjedan, a način bez tokena kaže im da prestanu trošiti. Možeš slati poruke prijateljima, a privatne poruke šifrirane su od kraja do kraja. Ploča govori oko 120 jezika, uključujući nizozemski, flamanski, gusarski i klingonski. Sve je besplatno, a nitko ti to ne pokušava ni prodati.","AI-gile je mali osobni projekt, a ne tvrtka. Rich je želio brinuti o nekoliko AI projekata bez otvaranja svake aplikacije da provjeri stanje, pa su on i agenti izgradili ploču za to, a zatim su tu ploču koristili za gradnju ostatka sebe. U zatvorenoj je pre-alfi, što znači da radi, uglavnom, za šačicu prijatelja. Nema stranice s cijenama, nema newslettera i nema plana rasta. Ako ti zvuči korisno, možeš se javiti da probaš kad se malo više otvori."]},{"n":144,"texts":["AI-gile je kanban ploča za jednog čovjeka i mnogo AI agenata. Radi na tvom računalu i potpuno je besplatna, bez računa i bez ikakvih tragača, a tvoji podaci ostaju kod tebe. Dodaješ projekte, a svaki projekt dobiva lead i mali tim. S leadom razgovaraš, pomalo kao na Discordu, i opišeš ideju; lead je pretvara u kartice i plan, pa čeka da pritisneš Go. Tim prolazi kroz kartice po prioritetu, koristeći jednostavnu naredbenu liniju napravljenu za jezične modele. Prije nego išta stigne natrag do tebe, AI tester prati korake u kopiji aplikacije i prilaže snimku zaslona. Gotov posao stiže na tvoju hrpu s promijenjenim datotekama i diffom. Prihvatiš ga ili ostaviš komentar, pa se tim probudi i pokuša ponovno. Samo ti možeš premjestiti karticu u Gotovo.","Otprilike ovako izgleda dan s AI-gileom. Navečer ostaviš nekoliko komentara: ovaj je gumb na krivom mjestu, taj popis treba sortirati, može li tamna tema. Odeš spavati. Agenti pročitaju komentare, naprave izmjene, testiraju ih i vrate ti ih. Ako stupac Na redu presuši, noćni čuvar ga puni iz backloga karticama kojima ne treba tvoj odgovor. Ujutro te čeka jedna kratka hrpa: par pitanja i nekoliko stvari za isprobati, svaka s koracima koje može pratiti pospana osoba i snimkom zaslona na kojoj radi. Pregledaš ih klikom, prihvatiš dobre, a ostale vratiš. Brojač tokena pokazuje koliko je sve to potrošilo, a način bez tokena tu je za štedljive tjedne. Zatim doručkuješ, a u tome ti agenti još ne mogu pomoći.","Prvo, što AI-gile nije. Nije startup, nije na prodaju i nitko ne prikuplja tvoje podatke. To je besplatna ploča koja radi na tvom računalu, bez računa, bez tragača i bez kolačića. Što jest: jedno uredno mjesto na kojem vidiš sve AI programerske projekte odjednom, s timom agenata koji rade kartice i tobom koji donosiš odluke. Spaja povezane kartice, ispravlja zbrkane naslove i pazi koliko kod ostaje vitak. Govori oko 120 jezika, od nizozemskog i flamanskog do gusarskog i klingonskog. Prijatelji mogu slati poruke jedni drugima, privatno i šifrirano. Izgradili su ga Rich i velik broj strpljivih agenata, uglavnom koristeći sam program. U zatvorenoj je pre-alfi, pa je mjestimice grub. Ako ti zvuči zabavno, lijepo zamoli i možda uđeš rano."]}],"quips":{"1":"Jedna riječ. Hrabro. Možda i previše hrabro.","3":"Tri riječi. Već iskrenije od većine stranica proizvoda.","8":"Osam riječi. I dalje kraće od stand-upa.","21":"Duljine su, usput, story pointovi. Naravno da jesu.","55":"Pedeset i pet riječi. Dok si čitao, dvije su kartice završene.","144":"To je ona duga. Nema 233. Agenti su otišli spavati."}},"timeline":{"first-idea.name":"Prva ideja","first-idea.line":"Sasvim prvi razgovor, prije nego što je postojao ijedan redak koda.","first-board.name":"Prva ploča","first-board.line":"Ploča koja prati vlastitu izgradnju: kartice, stupci, povuci i ispusti, projekti.","team-roles.name":"Tim i uloge","team-roles.line":"Profili agenata, predlošci timova, prostori i tko što radi.","install.name":"Instalacija i izdanja","install.line":"Zip koji prijatelj može instalirati, samoažuriranje, kanali i vraćanje unatrag.","usage-saver.name":"Štednja potrošnje","usage-saver.line":"Mjeri što pokretanja koštaju, drži kod vitkim, štedi svoj limit.","friends.name":"Prijatelji i dijeljenje","friends.line":"Privatne poruke, pomiješani relej, pozivnice, uloge i zajednički projekti.","languages.name":"Jezici","languages.line":"Svaki tekst na zaslonu u jezičnoj datoteci, prvo nizozemski i flamanski.","ai-tester.name":"AI tester","ai-tester.line":"Tester prvi provjerava svaku primopredaju i pokazuje što je vidio.","website.name":"Web-stranica","website.line":"aigile.lol, teaser i ova vremenska crta.","streaming.name":"Chat i streaming","streaming.line":"Discord, Twitch, OBS, streamerski način, GIF-ovi i emojiji.","no-ai.name":"Izdanje bez AI-ja","no-ai.line":"Ploča za ljude koji programiraju bez AI-ja i javne ploče.","night-watch.name":"Noćni čuvar","night-watch.line":"Čuvar i Scrum Master drže timove na zadatku dok ti spavaš.","p-more.name":"Sve ostalo","p-more.line":"Manje ideje koje još čekaju svoj red.","p-android.name":"Mobitel i Android","p-android.line":"Dođi do ploče s mobitela, a zatim prava Android aplikacija.","p-release.name":"Alfa i dalje","p-release.line":"Zatvorena alfa, stranica uživo, zatim beta.","p-languages.name":"Još jezika","p-languages.line":"130 jezika i način uranjanja za one koji uče.","p-engines.name":"Još AI motora","p-engines.line":"Odaberi Claude, Codex, Gemini, Copilot ili Cursor za svakog agenta.","p-pro.name":"Profesionalna praksa","p-pro.line":"Oznake rizika, merge vrata, kartice incidenata i zaštitne ograde.","p-self.name":"Briga o tebi","p-self.line":"Način za umorne, podsjetnici za brigu o sebi i 4:20.","p-servers.name":"Poslužitelji i rast","p-servers.line":"Globalne postavke poslužitelja, uloge i planiranje rasta.","p-livestream.name":"Streaming dodaci","p-livestream.line":"Twitch chat, vlastiti emojiji i javni prikaz uživo."},"words":{"button":"📖 Stručni pojmovi","h":"📖 Pojmovi objašnjeni","intro":"Riječi koje susrećeš u AI-gileu, jednostavno objašnjene: izrada, sigurno mijenjanje, održavanje rada za ljude koji ga koriste i timski rad s AI-jem.","search":"Traži riječ…","none":"Nijedna riječ ne odgovara.","close":"Zatvori","count":{"one":"{count} riječ","other":"{count} riječi"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ Izrada"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 Sigurno mijenjanje"},{"id":"run","name":"🛎️ Vođenje servisa"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have."},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Ideje i posao koji još nisu uvršteni u plan. Na njima se ništa ne radi dok se ne premjeste u stupac Na redu."},{"id":"sprint","g":"agile","word":"Sprint","text":"Kratko razdoblje rada (često tjedan ili dva) s dogovorenim skupom kartica koje treba završiti.","also":["sprintovi","sprinta","sprintu","sprintom","sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Brza provjera: što je svaki član tima napravio, što radi dalje i što ga koči.","also":["standup","stand-upovi","stand-upa","stand-upu","stand-ups"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Ploča sa stupcima (Na redu, U tijeku, Gotovo) na kojoj se kartice kreću slijeva nadesno kako posao napreduje."},{"id":"wip","g":"agile","word":"WIP ograničenje","text":"Work in progress, tj. posao u tijeku: najviše kartica koje stupac smije sadržavati, da tim završi stvari prije nego započne nove.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definicija gotovosti","text":"Kratak timski popis onoga što znači „gotovo”, npr. testirano i objašnjeno, prije nego što ti se kartica preda. Njezina blizanka, Definicija spremnosti, kaže kad je kartica dovoljno jasna da se počne.","also":["Definition of Done","Definicija spremnosti","Definition of Ready"]},{"id":"retro","g":"agile","word":"Retro","text":"Osvrt na to kako tim radi, da se dogovori jedna stvar koju treba poboljšati. U AI-gileu retro predlaže promjenu u načinu rada tima, a ti kažeš Go ili Još ne.","also":["retrospektiva","retrospektive","retros"]},{"id":"swarm","g":"agile","word":"Swarm","text":"Svi na palubu: svaki tim ostavlja drugi posao da pomogne na jednom hitnom projektu dok se ne riješi. Ostali projekti u međuvremenu čekaju.","also":["swarming","roj"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Onaj tko održava tok rada: uočava zapele kartice, potiče timove i podsjeća te što čeka. U AI-gileu to radi Lead Scrum Master na svim projektima.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Mapa projekta s kodom i cijelom poviješću commitova, obično pohranjena i na GitHubu.","also":["repozitorij","repository"]},{"id":"branch","g":"build","word":"Branch","text":"Zasebna linija rada u kodu, da se izmjene mogu raditi bez diranja glavne verzije.","also":["branchevi","grana","grane","branches"]},{"id":"commit","g":"build","word":"Commit","text":"Spremljena snimka koda s kratkom bilješkom o tome što se promijenilo. Uvijek se možeš vratiti na neku.","also":["commitovi","commita","commitu","commits"]},{"id":"push","g":"build","word":"Push","text":"Slanje spremljenih snimki (commitova) s ovog računala na GitHub, da budu sigurnosno kopirane i podijeljene."},{"id":"merge","g":"build","word":"Merge","text":"Spajanje izmjena iz brancha natrag u glavnu verziju."},{"id":"pr","g":"build","word":"Pull request","text":"Zahtjev da se izmjene iz brancha provjere i spoje u glavnu verziju.","also":["PR"]},{"id":"refactor","g":"build","word":"Refaktoriranje","text":"Uređivanje koda bez mijenjanja onoga što radi: manje datoteke, jasniji nazivi, manje ponavljanja."},{"id":"bug","g":"build","word":"Bug","text":"Nešto što ne radi onako kako bi trebalo.","also":["bugovi","buga","bugu","bugs"]},{"id":"peerreview","g":"build","word":"Recenzija kolege","text":"Drugi par očiju: drugi AI provjerava rad svake kartice prije nego što stigne do tebe, pa prolazi manje grešaka.","also":["peer review","code review","pregled koda"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor."},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiler"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"Isprobavanje gotovog posla da se provjeri radi li ono što je traženo, prije nego ga prihvatiš.","also":["testovi","testirati","testiranje","testiraš","testiraj","tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Kratica za quality assurance, osiguranje kvalitete: automatske provjere koje se pokreću prije nego što išta ide uživo. Kad je QA crven, nešto nije prošlo i ne može ići uživo dok se to ne popravi.","also":["provjere kvalitete","quality checks"]},{"id":"testpile","g":"test","word":"Hrpa za testiranje","text":"Gotove kartice koje čekaju da ih isprobaš, jednu za drugom. Prihvati jednu ili je vrati s napomenom, i dolazi sljedeća.","also":["hrpe za testiranje","test pile"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Puštanje nove verzije uživo, na primjer na poslužitelj na kojem je ljudi koriste."},{"id":"release","g":"change","word":"Izdanje","text":"Imenovani paket završenog rada koji ide uživo zajedno, s kratkim bilješkama o tome što se promijenilo. 🚀 Izdanja pišu bilješke iz gotovih kartica.","also":["izdanja","release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"Povratak na zadnju verziju koja je radila kad nova napravi probleme. U AI-gileu stvara popis koraka za poništavanje zapisanih na svakoj promjeni.","also":["roll back","vraćanje na staro"]},{"id":"live","g":"change","word":"Uživo","text":"Prava verzija koju ljudi koriste, za razliku od kopije za isprobavanje. Programeri je zovu i produkcija.","also":["produkcija","production","live"],"noTip":1},{"id":"change","g":"change","word":"Promjena","text":"Planirana promjena nečega o čemu ljudi ovise, unaprijed zapisana: što, zašto, rizik, kada i kako je poništiti. Pokreni je s 🔀 Podnesi promjenu.","also":["promjene","zahtjev za promjenu","change request"],"noTip":1},{"id":"risk","g":"change","word":"Rizik","text":"Nešto što bi moglo poći po zlu, ocijenjeno prema tome koliko je vjerojatno i koliko bi bilo loše. ⚠️ Rizici ih drže na jednom popisu, s najvišom ocjenom na vrhu, svaki s datumom za ponovni pregled.","also":["rizici","registar rizika","risk register"]},{"id":"chgwin","g":"change","word":"Prozor promjena","text":"Vrijeme kad promjene smiju ići uživo, npr. miran utorak navečer. Izvan prozora kartica promjene ne može se završiti, osim ako je hitno.","also":["prozori promjena","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Brzo glasanje neposredno prije nego što promjena ide uživo: svatko tko mora odobriti kaže Go ili No go. Ide dalje samo kad se slože.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Odobrenje","text":"Čekanje na „da” prije početka rada. Kartica koju podnese prijatelj, ili promjena, čeka u ✅ Odobrenja dok je ne odobriš ili odbiješ.","also":["odobrenja","approval"]},{"id":"quiettime","g":"change","word":"Mirno razdoblje","text":"Razdoblje, poput streama, demonstracije ili noći, kad ništa ne ide uživo. Timovi nastavljaju raditi i testirati, ali puštanje uživo čeka dok ne završi. Drugdje se to zove zamrzavanje promjena.","also":["mirna razdoblja","zamrzavanje promjena","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company."},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Servis","text":"Nešto što si napravio, a ljudi o tome ovise, poput web-stranice ili aplikacije, o čemu se brine da nastavi raditi. Označi „Ovaj projekt je servis” i reci što nudi, tko ga koristi i tko je dežuran.","also":["servisi","usluga","service"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Provjera dostupnosti","text":"Automatska provjera, svakih nekoliko minuta, da tvoj servis još odgovara. Ako nekoliko puta zaredom ne uspije, AI-gile sam otvara karticu incidenta.","also":["uptime","dostupnost","provjere dostupnosti"]},{"id":"statuspage","g":"run","word":"Statusna stranica","text":"Javna stranica koja pokazuje radi li servis (zeleno, narančasto ili crveno) uz najnoviju obavijest, kako bi ljudi koji ga koriste mogli sami provjeriti umjesto da pitaju.","also":["statusne stranice","status page"]},{"id":"desk","g":"run","word":"Servisni pult","text":"Mjesto na koje stižu pitanja i prijave ljudi koji koriste tvoj servis. AI-gile svaku razvrsta u zahtjev, incident ili ideju i javi kad izgleda kao nešto što je već prijavljeno.","also":["servisni pultovi","služba za pomoć","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Servisni zahtjev","text":"Netko traži nešto uobičajeno, poput novog računa ili malo pomoći, umjesto da prijavi da je nešto pokvareno. Čeka svoj red; incident ide prvi.","also":["servisni zahtjevi"]},{"id":"incident","g":"run","word":"Incident","text":"Nešto što je upravo sada pokvareno za ljude koji to koriste, npr. web-stranica ne radi. Kartica 🔥 incidenta preskače red: ponovno pokretanje ima prednost.","also":["incidenti","incidenta","incident"]},{"id":"major","g":"run","word":"Veliki incident","text":"Ozbiljan incident: pogođeno je mnogo ljudi ili su novac ili podaci u opasnosti. Jedan gumb stavlja sve timove na njega (swarm), budi onoga tko je dežuran i traži novu obavijest o statusu svakih 30 minuta.","also":["veliki incidenti","major incident"]},{"id":"oncall","g":"run","word":"Dežurstvo","text":"Biti onaj koji odgovara kad se nešto pokvari, čak i noću. Svaki servis ima dežurnog člana tima kojeg se prvog budi za njegove incidente.","also":["dežuran","dežurni","on call","on-call"]},{"id":"replyby","g":"run","word":"Rok za odgovor","text":"Koliko kartica smije čekati prvi odgovor, npr. sat vremena za incident. Nakon toga dobiva crveni sat, da se ništa tiho ne zaboravi. Zove se i ciljano vrijeme odgovora.","also":["rokovi za odgovor","ciljano vrijeme odgovora","response target"]},{"id":"postmortem","g":"run","word":"Analiza incidenta","text":"Kratak osvrt nakon incidenta: što se dogodilo, što je pomoglo i što promijeniti, bez okrivljavanja ikoga. Incident se ne može zatvoriti bez nje.","also":["post-mortem","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"Skriveni uzrok jednog ili više incidenata. Kartica 🧩 problem okuplja incidente koji se stalno vraćaju, kako bi se uzrok pronašao i zauvijek popravio.","also":["problemi","problema","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Temeljni uzrok","text":"Pravi razlog zašto se nešto pokvarilo, ne samo ono što si vidio da ne radi. Popravi temeljni uzrok i incident se prestaje vraćati.","also":["korijenski uzrok","root cause"]},{"id":"workaround","g":"run","word":"Zaobilazno rješenje","text":"Način da stvari rade dok pravi popravak ne bude spreman, npr. ponovno pokretanje nečega kad zapne. Zapisuje se na karticu problema da ga nitko ne mora ponovno smišljati.","also":["zaobilazna rješenja","workaround"]},{"id":"knownerror","g":"run","word":"Poznata greška","text":"Problem čiji je uzrok jasan i koji ima zaobilazno rješenje, ali još nije popravljen. 🧩 Poznate greške ih navode, kako bi svi koristili zaobilazno rješenje umjesto da ponovno kopaju.","also":["poznate greške","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Upute korak po korak za popravak poznate vrste problema, da se svaki put napravi isto i brzo. Nakon velikog incidenta tim ti može predložiti jedan da mu daš OK.","also":["runbooks","runbooka"]},{"id":"ci","g":"run","word":"Konfiguracijska stavka","text":"Jedna stvar o kojoj tvoj servis ovisi, poput poslužitelja, domene, certifikata, ključa ili dobavljača. 🗂️ Konfiguracijske stavke navode ih po servisu, da vidiš na što incident utječe i što treba obnoviti ili sigurnosno kopirati.","also":["konfiguracijske stavke","konfiguracijskih stavki"]},{"id":"expiry","g":"run","word":"Datum isteka","text":"AI-gile prati datume poput isteka certifikata ili domene. Unutar 30 dana prije datuma napravi jednu karticu za obnovu, da ništa iznenada ne prestane raditi.","also":["datumi isteka","istek","praćenje isteka"]},{"id":"backup","g":"run","word":"Sigurnosna kopija","text":"Spremljena ranija kopija tvojih podataka, na koju se možeš osloniti ako se nešto izgubi ili ošteti. AI-gile svaki dan radi sigurnosnu kopiju tvojih ploča.","also":["sigurnosne kopije","backup","backups"]},{"id":"restore","g":"run","word":"Vraćanje","text":"Vraćanje podataka iz sigurnosne kopije. Sigurnosna kopija stvarno vrijedi tek kad znaš da se može vratiti, pa se isplati to povremeno isprobati.","also":["vratiti","vraćeno","restore"]},{"id":"svcreview","g":"run","word":"Pregled servisa","text":"Pogled unatrag na jedan mjesec servisa: otvoreni i popravljeni incidenti, koliko su brzo ljudi dobili odgovor, dostupnost i potrošeni tokeni. Mjesečni pregled to prikazuje za svaki servis.","also":["pregledi servisa","mjesečni pregled","mjesečni pregledi"]},{"id":"accessreview","g":"run","word":"Pregled pristupa","text":"Provjera svakih 90 dana tko još može ući: poveznice za dijeljenje, uloge prijatelja i spremljene tajne. Svaku stavku zadržiš ili ukloniš, da stari pristupi ne ostanu visjeti.","also":["pregledi pristupa"]},{"id":"improvements","g":"run","word":"Popis poboljšanja","text":"Sve u čemu je tim odlučio postati bolji, na jednom mjestu: prijedlozi s retrospektive, akcije pregleda i popravci problema, svaki sa svojim statusom. Nađi ga pod 📈 Poboljšanja.","also":["popisi poboljšanja","poboljšanja"]},{"id":"tokencap","g":"run","word":"Limit tokena","text":"Mjesečno ograničenje tokena koje agenti jednog servisa smiju potrošiti. Na 80% dobivaš upozorenje; na 100% njihov rad u pozadini čeka sljedeći mjesec ili dok ne podigneš limit.","also":["limiti tokena","token cap"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day."},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice."},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing."},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service."},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"AI koji samostalno radi na zadatku: čita kod, mijenja ga, pokreće provjere i javlja natrag.","also":["agenti","agenta","agentu","agents"]},{"id":"token","g":"ai","word":"Token","text":"Jedinica u kojoj se broji AI potrošnja: otprilike nekoliko slova pročitanog ili napisanog teksta. Manje tokena, više paketa ostaje.","also":["tokeni","tokena","tokenu","tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Mala naredba koja se sama pokreće u zadanom trenutku, npr. kad počne AI sesija, da tim čuje tvoje komentare.","also":["hookovi","hooka","hookove","hook","hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results."},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers."},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
